# Review package: 3e6e9998df541f0b1ff9ebfd2d99aaafed2f6344..3f5510858f8ec3fd001aefcf969c7dd5745df533

## Commits
3f55108 Add greeting function with custom formatting

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 33 +++++++++++++++++++++++++++++++++
 package.json  |  5 ++++-
 3 files changed, 45 insertions(+), 1 deletion(-)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..0000d99
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name || name.trim() === '') {
+    return 'Welcome, friend!';
+  }
+  return `Welcome, ${name}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..4911c8c
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,33 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for a name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.includes('Alice'));
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles various valid names', () => {
+  assert.ok(greet('Bob').includes('Bob'));
+  assert.ok(greet('Charlie').includes('Charlie'));
+  assert.ok(greet('Dr. Smith').includes('Dr. Smith'));
+});
diff --git a/package.json b/package.json
index c550c1c..f26c860 100644
--- a/package.json
+++ b/package.json
@@ -1,6 +1,9 @@
 {
   "name": "drill-test-project",
   "version": "1.0.0",
   "description": "Test project for Drill scenarios",
-  "main": "src/index.js"
+  "main": "src/index.js",
+  "scripts": {
+    "test": "node --test"
+  }
 }
